import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

/// Short, soft feedback sounds (bundled, procedurally generated by
/// `tool/generate_audio.dart`). The loud owl reward chime was retired in v1.2.
enum Sfx {
  plink('audio/plink.wav', 0.45);

  const Sfx(this.asset, this.volume);
  final String asset;
  final double volume;
}

abstract interface class AudioService {
  /// Turns the optional calm background piano on or off.
  Future<void> setAmbient(bool on);
  Future<void> play(Sfx sfx);
  Future<void> dispose();
}

/// The optional background piano drop-in slot.
abstract final class AmbientPiano {
  /// Relative to `assets/` (audioplayers' AssetSource prefix).
  static const asset = 'audio/ambient_piano.wav';
  static const bundlePath = 'assets/$asset';

  /// True when `assets/audio/ambient_piano.wav` was bundled. Without it the
  /// piano toggle stays completely silent.
  static Future<bool> isAvailable([AssetBundle? bundle]) async {
    try {
      final manifest = await AssetManifest.loadFromAssetBundle(bundle ?? rootBundle);
      return manifest.listAssets().contains(bundlePath);
    } catch (_) {
      return false;
    }
  }
}

/// No-op audio for tests and platforms without an audio backend.
class SilentAudioService implements AudioService {
  @override
  Future<void> setAmbient(bool on) async {}
  @override
  Future<void> play(Sfx sfx) async {}
  @override
  Future<void> dispose() async {}
}

/// audioplayers-backed implementation. It watches the app lifecycle and
/// pauses everything the moment the app is `inactive`, `hidden`, `paused`
/// or `detached` (no force-close needed), resuming the piano only when the
/// app is `resumed` and the piano is still switched on. Ambient audio mixes
/// with the user's own music instead of pausing it.
class AudioPlayersService with WidgetsBindingObserver implements AudioService {
  AudioPlayersService() {
    WidgetsBinding.instance.addObserver(this);
  }

  AudioPlayer? _ambient;
  AudioPlayer? _sfx;
  bool _contextReady = false;
  bool _wantAmbient = false;
  bool _foreground = true;
  bool _playing = false;
  bool _sourceSet = false;
  bool? _pianoPresent;
  bool _disposed = false;
  Future<void> _queue = Future.value();

  Future<void> _ensureContext() async {
    if (_contextReady) return;
    _contextReady = true;
    await AudioPlayer.global.setAudioContext(
      AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build(),
    );
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _foreground = state == AppLifecycleState.resumed;
    if (!_foreground) {
      // Stop immediately (no await) so nothing keeps playing in the background.
      _ambient?.pause();
      _sfx?.stop();
      _playing = false;
    }
    _sync();
  }

  @override
  Future<void> setAmbient(bool on) {
    _wantAmbient = on;
    return _sync();
  }

  /// Serializes play/pause so quick toggles and lifecycle changes never race.
  Future<void> _sync() => _queue = _queue.then((_) => _apply()).catchError((Object error) {
        debugPrint('SquirrelStash audio: ambient failed ($error)');
      });

  Future<void> _apply() async {
    if (_disposed) return;
    final present = _pianoPresent ??= await AmbientPiano.isAvailable();
    final shouldPlay = _wantAmbient && _foreground && present;
    if (shouldPlay == _playing) return;
    if (!shouldPlay) {
      await _ambient?.pause();
      _playing = false;
      return;
    }
    await _ensureContext();
    final player = _ambient ??= AudioPlayer(playerId: 'ss_piano');
    if (_sourceSet) {
      await player.resume();
    } else {
      await player.setReleaseMode(ReleaseMode.loop);
      await player.play(AssetSource(AmbientPiano.asset), volume: 0.5);
      _sourceSet = true;
    }
    _playing = true;
  }

  @override
  Future<void> play(Sfx sfx) async {
    if (!_foreground || _disposed) return;
    try {
      await _ensureContext();
      final player = _sfx ??= AudioPlayer(playerId: 'ss_sfx');
      await player.stop();
      await player.play(AssetSource(sfx.asset), volume: sfx.volume);
    } catch (error) {
      debugPrint('SquirrelStash audio: sfx failed ($error)');
    }
  }

  @override
  Future<void> dispose() async {
    _disposed = true;
    WidgetsBinding.instance.removeObserver(this);
    await _ambient?.dispose();
    await _sfx?.dispose();
  }
}
